def fill_work(apps, schema_editor):
    InventoryLog = apps.get_model('inventory', 'InventoryLog')
    for log in InventoryLog.objects.all().only('id', 'action', 'description'):
        work, reference = '', ''
        for pattern, name in RULES:
            match = pattern.search(log.description or '')
            if match:
                work, reference = name, match.group(1)[:30]
                break
        if not work and log.action == 'TRANSFER':
            work = '이동'
        elif not work and log.action in ('IN', 'OUT'):
            work = '조정'
        if work:
            InventoryLog.objects.filter(pk=log.pk).update(work=work, reference=reference)


